import org.junit.Test;
import java.util.Locale;

import com.adobe.epubcheck.api.Report;
import com.adobe.epubcheck.util.EPUBVersion;
import com.adobe.epubcheck.api.EPUBProfile;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class EpubCheckerTest {

    private final EpubChecker epubChecker = new EpubChecker();

    @Test
    public void getLocaleDefaultTest() {
        assertEquals(new Locale("en", "US"), epubChecker.getLocale());
    }

    @Test
    public void runNullArgsTest() {
        assertEquals(1, epubChecker.run(null));
    }

    @Test
    public void runEmptyArgsTest() {
        assertEquals(1, epubChecker.run(new String[]{}));
    }

    @Test
    public void processEpubFileNullArgsTest() {
        assertEquals(1, epubChecker.processEpubFile(null));
    }

    @Test
    public void processEpubFileEmptyArgsTest() {
        assertEquals(1, epubChecker.processEpubFile(new String[]{}));
    }

    @Test
    public void validateFileTest() {
        final String path = "path/to/file.txt";
        final EPUBVersion version = EPUBVersion.VERSION_2;
        final Report report = mock(Report.class);
        final EPUBProfile profile = EPUBProfile.DEFAULT;

        assertEquals(0, epubChecker.validateFile(path, version, report, profile));

        verify(report, times(1)).info(path, 0, "VALID");
    }
}
